import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Home from './components/Home';
import Timetable from './components/Timetable';
import Teachers from './components/Teachers';
import About from './components/About';
import LmsDashboard from './components/LmsDashboard';
import Footer from './components/Footer';
import Sidebar from './components/Sidebar';

export default function App() {
  const [currentPage, setCurrentPage] = useState('Home');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [studentName, setStudentName] = useState('');
  const [inputName, setInputName] = useState('');
  const [inputPassword, setInputPassword] = useState('');

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    setShowLoginModal(false);
    try {
      const response = await fetch('http://localhost:5000/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: inputName, password: inputPassword })
      });
      const data = await response.json();
      if (data.status === 'Success') {
        setStudentName(inputName);
        setIsLoggedIn(true);
        setShowLoginModal(false);
        setCurrentPage('Dashboard');
      } else {
        alert('Invalid Username or Password!');
      }
    } catch (error) {
      alert('Error: Server connection failed!');
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setStudentName('');
    setInputName('');
    setInputPassword('');
    setCurrentPage('Home');
  };

return (
  <div style={{ position: 'relative', minHeight: '100vh' }}>

     <div style={{ display: 'flex' }}>
      <Sidebar /> {/* වම් පැත්තේ Sidebar එක */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
        <Navbar /> {/* උඩින් Navbar එක */}
        <div style={{ padding: '20px' }}>
          <LmsDashboard /> {/* මැද Dashboard එක */}
        </div>
      </div>
    </div>
  );
export default App;

    <main>
      {currentPage === 'Home' && <Home />}
      {currentPage === 'Classes' && <Timetable setCurrentPage={setCurrentPage} />}
      {currentPage === 'Teachers' && <Teachers />}
      {currentPage === 'About' && <About />}
      {currentPage === 'Dashboard' && <LmsDashboard username={studentName} onLogout={handleLogout} />}
    </main>

    <Footer />

{showLoginModal && (
  <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 9999, backdropFilter: 'blur(5px)' }}>
    <div style={{ width: '900px', height: '500px', background: '#fff', borderRadius: '25px', overflow: 'hidden', display: 'flex', boxShadow: '0 20px 50px rgba(0,0,0,0.3)', position: 'relative' }}>
      
      <div onClick={() => setShowLoginModal(false)} style={{ position: 'absolute', top: '20px', left: '20px', zIndex: 10000, cursor: 'pointer', fontSize: '30px', color: '#fff', fontWeight: 'bold' }}>←</div>

      <div style={{ flex: 1, backgroundImage: `url(${require('./1779942008594.png')})`, backgroundSize: 'cover', backgroundPosition: 'center' }}></div>

      <div style={{ flex: 1, padding: '60px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
        <h2 style={{ fontSize: '36px', color: '#388e3c', marginBottom: '30px', fontWeight: '700' }}>Welcome Back!</h2>
        <form onSubmit={handleLoginSubmit}>
          <div style={{ marginBottom: '20px' }}>
            <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', color: '#222' }}>User Name</label>
            <input type="text" placeholder="Enter your user name" required onChange={(e) => setInputName(e.target.value)} style={{ width: '100%', padding: '15px', borderRadius: '12px', border: '1px solid #d8f3dc', outline: 'none', backgroundColor: '#f1f8f2' }} />
          </div>
          <div style={{ marginBottom: '20px' }}>
            <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', color: '#222' }}>Password</label>
            <input type="password" placeholder="Enter your password" required onChange={(e) => setInputPassword(e.target.value)} style={{ width: '100%', padding: '15px', borderRadius: '12px', border: '1px solid #d8f3dc', outline: 'none', backgroundColor: '#f1f8f2' }} />
          </div>
          <p style={{ fontSize: '12px', color: '#666', marginBottom: '20px' }}>If you have forgotten your username or password, please contact the class to retrieve it.</p>
          <button type="submit" style={{ width: '100%', padding: '15px', border: 'none', borderRadius: '12px', background: '#388e3c', color: '#fff', fontSize: '18px', fontWeight: '600', cursor: 'pointer' }}>Login</button>
        </form>
      </div>
    </div>
  </div>
)}
  </div>
);
}
